const conn = await amqp.connect(url);
const ch = await conn.createChannel();
await ch.assertQueue("orders", { durable: true });
ch.prefetch(10);
await ch.consume("orders", async (msg) => {
  try {
    await handle(JSON.parse(msg.content.toString()));
    ch.ack(msg);
  } catch (err) {
    ch.nack(msg, false, false);   // requeue=false -> dead-letter
  }
}, { noAck: false });
